function request(method, path, body) {
    return window.garmentDesktop.backendRequest({ method, path, body });
}
export function analyticsQuery(filters) {
    const parameters = new URLSearchParams();
    for (const [key, value] of Object.entries(filters)) {
        if (value)
            parameters.set(key, value);
    }
    const query = parameters.toString();
    return query ? `?${query}` : "";
}
export const api = {
    readiness: () => request("GET", "/api/readiness"),
    employees: (includeInactive = false) => request("GET", `/api/employees${includeInactive ? "?include_inactive=true" : ""}`),
    createEmployee: (input) => request("POST", "/api/employees", input),
    updateEmployee: (id, input) => request("PUT", `/api/employees/${id}`, input),
    deviceConfiguration: () => request("GET", "/api/device-configuration"),
    saveDeviceConfiguration: (input) => request("PUT", "/api/device-configuration", input),
    visionModels: () => request("GET", "/api/vision/models"),
    reloadVisionModels: () => request("POST", "/api/vision/models/load"),
    scanVisionCameras: (expectedCount) => request("GET", `/api/vision/cameras${expectedCount ? `?expected_count=${Math.min(5, expectedCount)}` : ""}`),
    testVisionCamera: (cameraId) => request("POST", "/api/vision/cameras/test", { camera_id: cameraId }),
    startVision: (sessionId, sourceType, videoPath) => request("POST", "/api/vision/start", {
        session_id: sessionId,
        source_type: sourceType,
        ...(videoPath ? { video_path: videoPath } : {}),
    }),
    stopVision: (sessionId) => request("POST", `/api/vision/stop/${sessionId}`),
    inferenceStatus: (sessionId) => request("GET", `/api/vision/status/${sessionId}`),
    activeSession: () => request("GET", "/api/sessions/active"),
    sessions: () => request("GET", "/api/sessions"),
    deleteSessionHistory: (confirmation) => request("POST", "/api/sessions/delete-history", { confirmation }),
    createSession: (input) => request("POST", "/api/sessions", input),
    completeSession: (id) => request("POST", `/api/sessions/${id}/complete`),
    dashboard: (id) => request("GET", `/api/sessions/${id}/dashboard`),
    addValidationPiece: (sessionId) => request("POST", `/api/sessions/${sessionId}/pieces`, { event_source: "VALIDATION" }),
    createValidationIotEvent: (sessionId, eventType) => request("POST", "/api/iot-events", {
        session_id: sessionId,
        event_type: eventType,
        event_source: "VALIDATION",
    }),
    testValidationController: () => request("POST", "/api/iot-events", {
        event_type: "RESET",
        event_source: "VALIDATION",
    }),
    analytics: (filters) => request("GET", `/api/analytics${analyticsQuery(filters)}`),
};
