export function describeSewingActivity(inference) {
    if (!inference || !inference.running)
        return "Monitoring not started";
    if (inference.phase === "PAUSED")
        return "Counting paused";
    if (inference.sewing_state === "SEWING")
        return "Sewing in progress";
    if (inference.sewing_state === "IDLE_SETUP")
        return "Ready for next garment";
    if (inference.sewing_state === "INVALID_VIEW")
        return "Workstation not visible";
    return "Checking workstation";
}
export function allowsRecordedWorkstationVideo(sessionMode) {
    return sessionMode === "VALIDATION" || sessionMode === "PRODUCTION";
}
